// generated by gemini-3.5-flash-lite for PR #6117 (round 0): deep_nesting_pretty_dump
// intent: Exercise pretty-printing dump(2) on a deeply nested object to invoke put_indent and literal helpers inside the serializer.
#include <nlohmann/json.hpp>
#include <iostream>
int main() {
    try {
        nlohmann::json j = 1;
        for (int i = 0; i < 40; ++i) {
            nlohmann::json obj;
            obj["nested"] = j;
            j = obj;
        }
        std::string s = j.dump(2);
        std::cout << (s.empty() ? "empty" : "non-empty") << std::endl;
    } catch (const std::exception& e) {
        std::cout << typeid(e).name() << ": " << e.what() << std::endl;
    }
}
